  "text.f3ff3d6aa6658685fcb9": "central first3years extra external funding USDm",
  "text.e479e3914d8a0034ba16": "central first3years extra external funding USDm · 2 records",
  "text.6c896d67d9d92206f32d": "central assumed cash settlement USDm per year",
  "text.5a92f6f089f63f0d476b": "instruction",
  "text.68638dc1febac2ffcdc5": "The executable central budget reserves1bn/year without claiming reported withholding. Cash funding equation must deduct employee award tax-withholding/settlement cash not already in OCF. Keep explicit unknown rather than treating all SBC addback as verified deployable funding.",
  "text.9cf96a9bc34596610f2d": "existing base deficit",
